mapper.select:
SELECT ID, NAME, PROJECT_NO, CATEGORY, UPDATED_AT FROM ( SELECT P.ID, P.NAME, P.PROJECT_NO, P.CATEGORY, P.UPDATED_AT, ROW_NUMBER() OVER (ORDER BY P.UPDATED_AT DESC, P.ID DESC) AS RN FROM PROJECT P WHERE
AND (INSTR(UPPER(P.NAME), UPPER(#{keyword})) > 0 OR INSTR(UPPER(P.PROJECT_NO), UPPER(#{keyword})) > 0)
) ELIGIBLE_PROJECT WHERE RN <= #{limit} ORDER BY RN
